SELECT
  arriving.reject_id,
  arriving.source_relation,
  arriving.mapping,
  arriving.mapping_version,
  arriving.failed_rules,
  arriving.key_values,
  arriving.raw,
  arriving._load_id,
  arriving._ingested_at,
  arriving._source_row_id,
  COALESCE(incumbent.first_seen, arriving.first_seen) AS first_seen,
  arriving.last_seen,
  arriving.resolved_at,
  COALESCE(incumbent.last_evaluated_at, arriving.last_evaluated_at) AS last_evaluated_at
FROM (
  SELECT
    _extract.reject_id,
    _extract.source_relation,
    _extract.mapping,
    _extract.mapping_version,
    ARRAY_CAT(
      ARRAY_CAT(
        ARRAY_CAT(
          ARRAY_CAT(
            ARRAY_CAT(
              ARRAY_CAT(
                ARRAY_CAT(
                  ARRAY_CAT(
                    CASE
                      WHEN _extract._branch_amount_coercible
                      THEN ARRAY['amount_coercible']
                      ELSE CAST(ARRAY[] AS TEXT[])
                    END,
                    CASE
                      WHEN _extract.amount < 0
                      THEN ARRAY['amount_range_min']
                      ELSE CAST(ARRAY[] AS TEXT[])
                    END
                  ),
                  CASE
                    WHEN _extract._branch_code_coercible
                    THEN ARRAY['code_coercible']
                    ELSE CAST(ARRAY[] AS TEXT[])
                  END
                ),
                CASE
                  WHEN _extract._win_code_unique
                  THEN ARRAY['code_unique']
                  ELSE CAST(ARRAY[] AS TEXT[])
                END
              ),
              CASE
                WHEN _extract._branch_line_no_coercible
                THEN ARRAY['line_no_coercible']
                ELSE CAST(ARRAY[] AS TEXT[])
              END
            ),
            CASE
              WHEN _extract._branch_order_date_coercible
              THEN ARRAY['order_date_coercible']
              ELSE CAST(ARRAY[] AS TEXT[])
            END
          ),
          CASE
            WHEN _extract._branch_order_id_coercible
            THEN ARRAY['order_id_coercible']
            ELSE CAST(ARRAY[] AS TEXT[])
          END
        ),
        CASE
          WHEN _extract._branch_status_coercible
          THEN ARRAY['status_coercible']
          ELSE CAST(ARRAY[] AS TEXT[])
        END
      ),
      CASE
        WHEN NOT _extract.status IN ('open', 'closed')
        THEN ARRAY['status_in_set']
        ELSE CAST(ARRAY[] AS TEXT[])
      END
    ) AS failed_rules,
    JSON_BUILD_OBJECT('line_no', _extract.line_no, 'order_id', _extract.order_id) AS key_values,
    _extract._raw AS raw,
    _extract._load_id,
    _extract._ingested_at,
    _extract._source_row_id,
    _extract._ingested_at AS first_seen,
    _extract._ingested_at AS last_seen,
    CAST(NULL AS TIMESTAMP) AS resolved_at,
    CAST(NULL AS TIMESTAMP) AS last_evaluated_at
  FROM (
    SELECT
      *,
      (
        COUNT(*) OVER (PARTITION BY code) > 1 AND (
          NOT code IS NULL
        )
      ) AS _win_code_unique
    FROM (
      SELECT
        amount,
        code,
        line_no,
        order_date,
        order_id,
        status,
        _ingested_at,
        _load_id,
        _source_row_id,
        _branch_amount_coercible,
        _branch_code_coercible,
        _branch_line_no_coercible,
        _branch_order_date_coercible,
        _branch_order_id_coercible,
        _branch_status_coercible,
        _raw,
        reject_id,
        source_relation,
        mapping,
        mapping_version
      FROM (
        SELECT
          CASE
            WHEN PG_INPUT_IS_VALID(amount, 'DECIMAL(38, 9)')
            THEN CAST(amount AS DECIMAL(38, 9))
          END AS amount,
          CASE WHEN PG_INPUT_IS_VALID(code, 'TEXT') THEN CAST(code AS TEXT) END AS code,
          CASE WHEN PG_INPUT_IS_VALID(line_no, 'BIGINT') THEN CAST(line_no AS BIGINT) END AS line_no,
          CASE
            WHEN PG_INPUT_IS_VALID(order_date, 'DATE')
            AND NOT LOWER(order_date) ~ '^[[:space:]]*(now|today|tomorrow|yesterday)[[:space:]]*$'
            THEN CAST(order_date AS DATE)
          END AS order_date,
          CASE WHEN PG_INPUT_IS_VALID(order_id, 'TEXT') THEN CAST(order_id AS TEXT) END AS order_id,
          CASE WHEN PG_INPUT_IS_VALID(status, 'TEXT') THEN CAST(status AS TEXT) END AS status,
          _ingested_at,
          _load_id,
          _source_row_id,
          CASE
            WHEN PG_INPUT_IS_VALID(amount, 'DECIMAL(38, 9)')
            THEN CAST(amount AS DECIMAL(38, 9))
          END IS NULL
          AND (
            NOT amount IS NULL
          ) AS _branch_amount_coercible,
          CASE WHEN PG_INPUT_IS_VALID(code, 'TEXT') THEN CAST(code AS TEXT) END IS NULL
          AND (
            NOT code IS NULL
          ) AS _branch_code_coercible,
          CASE WHEN PG_INPUT_IS_VALID(line_no, 'BIGINT') THEN CAST(line_no AS BIGINT) END IS NULL
          AND (
            NOT line_no IS NULL
          ) AS _branch_line_no_coercible,
          CASE
            WHEN PG_INPUT_IS_VALID(order_date, 'DATE')
            AND NOT LOWER(order_date) ~ '^[[:space:]]*(now|today|tomorrow|yesterday)[[:space:]]*$'
            THEN CAST(order_date AS DATE)
          END IS NULL
          AND (
            NOT order_date IS NULL
          ) AS _branch_order_date_coercible,
          CASE WHEN PG_INPUT_IS_VALID(order_id, 'TEXT') THEN CAST(order_id AS TEXT) END IS NULL
          AND (
            NOT order_id IS NULL
          ) AS _branch_order_id_coercible,
          CASE WHEN PG_INPUT_IS_VALID(status, 'TEXT') THEN CAST(status AS TEXT) END IS NULL
          AND (
            NOT status IS NULL
          ) AS _branch_status_coercible,
          JSON_BUILD_OBJECT(
            '_ingested_at',
            _ingested_at,
            '_load_id',
            _load_id,
            '_source_row_id',
            _source_row_id,
            'amount',
            amount,
            'code',
            code,
            'line_no',
            line_no,
            'order_date',
            order_date,
            'order_id',
            order_id,
            'status',
            status
          ) AS _raw,
          ENCODE(
            SHA256(
              CONVERT_TO(
                'S8:q__lines' || 'S' || CAST(LENGTH(_source_row_id) AS TEXT) || ':' || _source_row_id,
                'UTF8'
              )
            ),
            'hex'
          ) AS reject_id,
          'q__lines' AS source_relation,
          'q__lines->q_line' AS mapping,
          1 AS mapping_version,
          ROW_NUMBER() OVER (
            PARTITION BY CASE WHEN PG_INPUT_IS_VALID(order_id, 'TEXT') THEN CAST(order_id AS TEXT) END, CASE WHEN PG_INPUT_IS_VALID(line_no, 'BIGINT') THEN CAST(line_no AS BIGINT) END
            ORDER BY _ingested_at DESC NULLS LAST, _load_id DESC NULLS LAST, _source_row_id DESC NULLS LAST
          ) AS _w
        FROM {{ source('bronze', 'q__lines') }}
      ) AS _t
      WHERE
        _w = 1
    ) AS _deduped
  ) AS _extract
  WHERE
    COALESCE(
      (
        _extract._branch_amount_coercible
        OR _extract._branch_code_coercible
        OR _extract._branch_line_no_coercible
        OR _extract._branch_order_date_coercible
        OR _extract._branch_order_id_coercible
        OR _extract._branch_status_coercible
        OR (
          NOT _extract.status IN ('open', 'closed')
        )
        OR _extract._win_code_unique
      ),
      FALSE
    )
) AS arriving
LEFT JOIN {{ this }} AS incumbent
  ON arriving.reject_id = incumbent.reject_id

